template:
fn pair_coords(xs: &[i32], ys: &[i32]) -> Vec<(i32, i32)> {
    xs.iter()
        .⟦slot1⟧(ys.iter())
        .⟦slot2⟧(|(&x, &y)| (x, y))
        .collect()
}

fn main() {
    let xs = vec![1, 2];
    let ys = vec![10, 20];
    println!("{:?}", pair_coords(&xs, &ys));
}

tests:
#[test]
fn pairs_equal_lengths() {
    let xs = vec![1, 2, 3];
    let ys = vec![10, 20, 30];
    assert_eq!(pair_coords(&xs, &ys), vec![(1, 10), (2, 20), (3, 30)]);
}

#[test]
fn stops_at_shortest() {
    let xs = vec![1, 2];
    let ys = vec![10, 20, 30, 40];
    assert_eq!(pair_coords(&xs, &ys), vec![(1, 10), (2, 20)]);
}
